  'series.loading': { 'pt-BR':'Carregando a série histórica…', en:'Loading the historical series…', es:'Cargando la serie histórica…', de:'Historische Reihe wird geladen…', fr:'Chargement de la série historique…', ru:'Загрузка исторического ряда…', 'zh-CN':'正在加载历史序列…', ja:'時系列を読み込んでいます…', ko:'시계열을 불러오는 중…', pl:'Ładowanie szeregu historycznego…' },
