  'series.preparing': { 'pt-BR':'Preparando o gráfico…', en:'Preparing the chart…', es:'Preparando el gráfico…', de:'Diagramm wird vorbereitet…', fr:'Préparation du graphique…', ru:'Подготовка графика…', 'zh-CN':'正在准备图表…', ja:'グラフを準備しています…', ko:'차트를 준비하는 중…', pl:'Przygotowywanie wykresu…' },
