  'series.data': { 'pt-BR':'Dados da série', en:'Series data', es:'Datos de la serie', de:'Reihendaten', fr:'Données de la série', ru:'Данные ряда', 'zh-CN':'序列数据', ja:'系列データ', ko:'계열 데이터', pl:'Dane serii' },
  'series.method': { 'pt-BR':'Método e revisões', en:'Method and revisions', es:'Método y revisiones', de:'Methode und Revisionen', fr:'Méthode et révisions', ru:'Метод и пересмотры', 'zh-CN':'方法和修订', ja:'方法と改訂', ko:'방법 및 개정', pl:'Metoda i rewizje' },
