  'series.sourceLabel': { 'pt-BR':'Fonte:', en:'Source:', es:'Fuente:', de:'Quelle:', fr:'Source :', ru:'Источник:', 'zh-CN':'来源：', ja:'情報源：', ko:'출처:', pl:'Źródło:' },
  'series.viewSource': { 'pt-BR':'Ver origem', en:'View source', es:'Ver fuente', de:'Quelle ansehen', fr:'Voir la source', ru:'Открыть источник', 'zh-CN':'查看来源', ja:'情報源を見る', ko:'출처 보기', pl:'Zobacz źródło' },
  'guide.title': { 'pt-BR':'Entenda este indicador', en:'Understand this indicator', es:'Entienda este indicador', de:'Diesen Indikator verstehen', fr:'Comprendre cet indicateur', ru:'Как понимать этот показатель', 'zh-CN':'读懂这项指标', ja:'この指標を理解する', ko:'이 지표 이해하기', pl:'Jak rozumieć ten wskaźnik' },
  'guide.what': { 'pt-BR':'O que é?', en:'What is it?', es:'¿Qué es?', de:'Was ist das?', fr:'Qu’est-ce que c’est ?', ru:'Что это?', 'zh-CN':'这是什么？', ja:'何を示す？', ko:'무엇인가요?', pl:'Co to jest?' },
  'guide.read': { 'pt-BR':'Como ler?', en:'How do I read it?', es:'¿Cómo se interpreta?', de:'Wie liest man ihn?', fr:'Comment le lire ?', ru:'Как читать?', 'zh-CN':'如何阅读？', ja:'どう読む？', ko:'어떻게 읽나요?', pl:'Jak to odczytać?' },
  'guide.caution': { 'pt-BR':'Atenção', en:'Keep in mind', es:'Atención', de:'Wichtig', fr:'Attention', ru:'Важно', 'zh-CN':'请注意', ja:'注意点', ko:'주의', pl:'Uwaga' },
  'guide.readText': { 'pt-BR':'Cada ponto mostra {name}, medido em {unit}, para uma observação {frequency}. Leia o ano ou período junto com o valor.', en:'Each point shows {name}, measured in {unit}, for a {frequency} observation. Read the year or period together with the value.', es:'Cada punto muestra {name}, medido en {unit}, para una observación {frequency}. Lea el año o período junto con el valor.', de:'Jeder Punkt zeigt {name}, gemessen in {unit}, als {frequency} Beobachtung. Lesen Sie Zeitraum und Wert immer zusammen.', fr:'Chaque point montre {name}, mesuré en {unit}, pour une observation {frequency}. Lisez toujours la période avec la valeur.', ru:'Каждая точка показывает {name} в единицах {unit} для наблюдения с частотой «{frequency}». Читайте период вместе со значением.', 'zh-CN':'每个点表示{name}，单位为{unit}，频率为{frequency}。请将年份或时期与数值一起阅读。', ja:'各点は{name}を{unit}で示す{frequency}の観測値です。年または期間と数値を一緒に確認してください。', ko:'각 점은 {frequency} 관측치인 {name}을 {unit} 단위로 보여 줍니다. 연도 또는 기간과 값을 함께 읽으세요.', pl:'Każdy punkt pokazuje {name}, mierzone w {unit}, jako obserwację {frequency}. Odczytuj okres razem z wartością.' },
  'guide.cautionText': { 'pt-BR':'Compare valores somente quando definição, unidade e período forem equivalentes. Lacunas não significam zero.', en:'Compare values only when definition, unit and period are equivalent. A missing value does not mean zero.', es:'Compare valores solo cuando la definición, la unidad y el período sean equivalentes. Un dato ausente no significa cero.', de:'Vergleichen Sie Werte nur bei gleicher Definition, Einheit und Periode. Fehlende Werte bedeuten nicht null.', fr:'Ne comparez que des valeurs ayant la même définition, unité et période. Une donnée manquante ne signifie pas zéro.', ru:'Сравнивайте значения только при одинаковых определении, единице и периоде. Пропуск не означает ноль.', 'zh-CN':'只有定义、单位和时期一致时才能比较。缺失值不代表零。', ja:'定義・単位・期間が同じ場合にのみ比較してください。欠損値はゼロではありません。', ko:'정의, 단위, 기간이 같은 값만 비교하세요. 결측치는 0을 뜻하지 않습니다.', pl:'Porównuj wartości tylko przy zgodnej definicji, jednostce i okresie. Brak danych nie oznacza zera.' },
  'event.method': { 'pt-BR':'Método', en:'Method', es:'Método', de:'Methode', fr:'Méthode', ru:'Метод', 'zh-CN':'方法', ja:'方法', ko:'방법', pl:'Metoda' },
  'event.law': { 'pt-BR':'Lei / norma', en:'Law / rule', es:'Ley / norma', de:'Gesetz / Regel', fr:'Loi / règle', ru:'Закон / норма', 'zh-CN':'法律/规则', ja:'法律・規則', ko:'법률 / 규정', pl:'Ustawa / norma' },
  'event.context': { 'pt-BR':'Contexto', en:'Context', es:'Contexto', de:'Kontext', fr:'Contexte', ru:'Контекст', 'zh-CN':'背景', ja:'背景', ko:'맥락', pl:'Kontekst' },
  'history.eyebrow': { 'pt-BR':'1988—2026 · CONTEXTO DOCUMENTADO', en:'1988—2026 · DOCUMENTED CONTEXT', es:'1988—2026 · CONTEXTO DOCUMENTADO', de:'1988—2026 · DOKUMENTIERTER KONTEXT', fr:'1988—2026 · CONTEXTE DOCUMENTÉ', ru:'1988—2026 · ДОКУМЕНТИРОВАННЫЙ КОНТЕКСТ', 'zh-CN':'1988—2026 · 已记录的背景', ja:'1988—2026・記録された背景', ko:'1988—2026 · 문서화된 맥락', pl:'1988—2026 · UDOKUMENTOWANY KONTEKST' },
  'history.caution': { 'pt-BR':'Uma lei pode alterar incentivos, regras e instituições. Sua proximidade com uma mudança no gráfico não demonstra causalidade. Publicação, vigência e implementação podem ocorrer em datas diferentes.', en:'A law can change incentives, rules and institutions. Its proximity to a chart change does not prove causality. Publication, entry into force and implementation may occur on different dates.', es:'Una ley puede modificar incentivos, reglas e instituciones. Su proximidad a un cambio en el gráfico no prueba causalidad. La publicación, vigencia e implementación pueden ocurrir en fechas distintas.', de:'Ein Gesetz kann Anreize, Regeln und Institutionen ändern. Seine zeitliche Nähe zu einer Diagrammänderung beweist keine Kausalität. Veröffentlichung, Inkrafttreten und Umsetzung können zu unterschiedlichen Zeitpunkten erfolgen.', fr:'Une loi peut modifier les incitations, les règles et les institutions. Sa proximité avec un changement du graphique ne prouve pas une causalité. Publication, entrée en vigueur et mise en œuvre peuvent avoir lieu à des dates différentes.', ru:'Закон может менять стимулы, правила и институты. Близость по времени к изменению графика не доказывает причинность. Публикация, вступление в силу и реализация могут происходить в разные даты.', 'zh-CN':'法律可能改变激励、规则和制度。它与图表变化在时间上的接近并不能证明因果关系。发布、生效和实施可能发生在不同日期。', ja:'法律はインセンティブ、規則、制度を変え得ます。グラフの変化に時期が近いことは因果関係の証明ではありません。公布、施行、実施は異なる日付になり得ます。', ko:'법률은 유인, 규칙 및 제도를 바꿀 수 있습니다. 그래프 변화와 시기가 가깝다고 인과관계가 증명되지는 않습니다. 공표, 발효 및 시행은 서로 다른 날짜에 이뤄질 수 있습니다.', pl:'Ustawa może zmieniać bodźce, reguły i instytucje. Bliskość czasowa ze zmianą na wykresie nie dowodzi związku przyczynowego. Publikacja, wejście w życie i wdrożenie mogą nastąpić w różnych terminach.' },
