export function translate(locale: Locale, key: string, values: Record<string, string | number> = {}): string {
  const phrase = phrases[key]?.[locale] ?? phrases[key]?.['pt-BR'] ?? key
  return phrase.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? `{${name}}`))
}

/** Localize editorial names when a reviewed translation is available; preserve canonical source labels otherwise. */
export function localizedIndicator(locale: Locale, id: string, value: string, field: 'name' | 'description'): string {
  return phrases[`indicator.${id}.${field}`]?.[locale] ?? value
}

const countryRegions: Record<string, string> = { BRA: 'BR', USA: 'US', CHL: 'CL', ARG: 'AR', PRY: 'PY', URY: 'UY', MEX: 'MX', COL: 'CO', PER: 'PE', CHN: 'CN', IND: 'IN', ZAF: 'ZA' }

/** Use built-in locale data for country labels; the catalog identifier remains unchanged. */
export function localizedCountry(locale: Locale, id: string, value: string): string {
  const region = countryRegions[id]
  if (!region) return value
  try { return new Intl.DisplayNames([locale], { type: 'region' }).of(region) ?? value } catch { return value }
}

interface TranslationContextValue { locale: Locale; setLocale: (locale: Locale) => void; t: (key: string, values?: Record<string, string | number>) => string }
const TranslationContext = createContext<TranslationContextValue | null>(null)

function storedLocale(): Locale {
  try { const value = localStorage.getItem('observatorio:locale'); return locales.includes(value as Locale) ? value as Locale : 'pt-BR' } catch { return 'pt-BR' }
}

/** Provide the chosen interface language without sending it to external services. */
export function TranslationProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState(storedLocale)
  const setLocale = (next: Locale) => {
    document.documentElement.lang = next
    try { localStorage.setItem('observatorio:locale', next) } catch { /* Storage may be disabled; the current session still works. */ }
    setLocaleState(next)
  }
  document.documentElement.lang = locale
  const value = useMemo(() => ({ locale, setLocale, t: (key: string, values?: Record<string, string | number>) => translate(locale, key, values) }), [locale])
  return <TranslationContext.Provider value={value}>{children}</TranslationContext.Provider>
}

export function useTranslation(): TranslationContextValue {
  const value = useContext(TranslationContext)
  if (!value) throw new Error('TranslationProvider is required')
  return value
}
